      if (Object.prototype.hasOwnProperty.call(scope, "STRAIN_MAX")) STRAIN_MAX = scope["STRAIN_MAX"];
      if (Object.prototype.hasOwnProperty.call(scope, "STRAIN_MIN")) STRAIN_MIN = scope["STRAIN_MIN"];
